// ===================================================================
// 1. DATA VALIDATION & TELEMETRY SANITIZATION
// ===================================================================
const raw = $input.first().json.body || $input.first().json;

const device = String(raw.device || 'VORTEX-X-01');
const timestamp = raw.timestamp || new Date().toISOString();
const distance = Number(parseFloat(raw.distance_cm ?? raw.distance ?? 999).toFixed(1));
const temperature = Number(parseFloat(raw.temperature_c ?? raw.temperature ?? 28.0).toFixed(1));
const humidity = Number(parseFloat(raw.humidity_pct ?? raw.humidity ?? 60.0).toFixed(1));
const pirState = Number(raw.pir_state ?? raw.pir ?? 0) === 1 ? 1 : 0;
const aiScore = Number(parseFloat(raw.anomaly_score ?? raw.aiScore ?? 0.95).toFixed(2));
const gait = String(raw.gaitState || raw.command || 'STAND').toUpperCase();
const customMsg = raw.message ? String(raw.message) : '';

// Helper for mini visual progress bar in text
function makeBar(val, max, length = 8) {
  const ratio = Math.max(0, Math.min(1, val / max));
  const filled = Math.round(ratio * length);
  return '█'.repeat(filled) + '░'.repeat(length - filled);
}

const distanceBar = makeBar(Math.min(distance, 100), 100);
const tempBar = makeBar(Math.min(temperature, 50), 50);

return {
  json: {
    device,
    timestamp,
    distance,
    temperature,
    humidity,
    pirState,
    aiScore,
    gait,
    customMsg,
    distanceBar,
    tempBar,
    receivedAt: new Date().toISOString()
  }
};

// ===================================================================
// 2. ANTI-FLOOD DEBOUNCE FILTER & THREAT CLASSIFICATION
// ===================================================================
const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');

const now = Date.now();
const lastAlertTime = staticData.lastAlertTime || 0;
const lastPIRAlert = staticData.lastPIRAlert || 0;

let eventCategory = 'ROUTINE_TELEMETRY';
let threatLevel = 'NORMAL';

if (item.pirState === 1) {
  eventCategory = 'PIR_INTRUSION';
  threatLevel = 'CRITICAL';
} else if (item.distance <= 10.0) {
  eventCategory = 'OBSTACLE_HAZARD';
  threatLevel = 'WARNING';
} else if (item.aiScore < 0.65) {
  eventCategory = 'AI_ANOMALY';
  threatLevel = 'WARNING';
} else if (item.temperature >= 35.0) {
  eventCategory = 'OVERHEAT_WARNING';
  threatLevel = 'WARNING';
}

let allowNotification = true;

if (eventCategory === 'PIR_INTRUSION') {
  if (now - lastPIRAlert < 15000) {
    allowNotification = false;
  } else {
    staticData.lastPIRAlert = now;
  }
} else if (threatLevel === 'NORMAL' && (now - lastAlertTime < 25000)) {
  allowNotification = false;
}

if (allowNotification) {
  staticData.lastAlertTime = now;
}

// Prepare Groq prompt payload
const groqPrompt = `Telemetri Robot ${item.device}:
- Event: ${eventCategory} (Level: ${threatLevel})
- Sensor PIR (Gerakan): ${item.pirState === 1 ? 'AKTIF DETEKSI MANUSIA/OBJEK' : 'AMAN STANDBY'}
- HC-SR04 Jarak: ${item.distance} cm
- Suhu ESP32/Motor: ${item.temperature} °C, RH: ${item.humidity}%
- Model Anomaly Score: ${item.aiScore}
- Mode Gerak: ${item.gait}
- Catatan Tambahan: ${item.customMsg || '-'}`;

return {
  json: {
    ...item,
    eventCategory,
    threatLevel,
    allowNotification,
    groqPrompt,
    incidentId: 'VX-' + Math.floor(100000 + Math.random() * 900000)
  }
};

