// Extract Groq AI completion or provide robust fallback if API key not set yet
const prev = $('Anti-Flood & Classifier').item.json;
const groqResponse = $input.first().json;

let aiInsight = '';

if (groqResponse && groqResponse.choices && groqResponse.choices.length > 0) {
  aiInsight = groqResponse.choices[0].message.content.trim();
} else if (groqResponse && groqResponse.error) {
  aiInsight = `[Groq API Notifikasi]: ${groqResponse.error.message || 'Kunci API Groq belum dimasukkan. Masukkan API Key Anda pada node Groq AI.'}`;
} else {
  // Intelligent local fallback if Groq key isn't active yet
  if (prev.eventCategory === 'PIR_INTRUSION') {
    aiInsight = 'Terdeteksi gerakan pada sektor depan robot. Disarankan verifikasi visual atau aktifkan alarm buzzer untuk perimeter defense.';
  } else if (prev.eventCategory === 'OBSTACLE_HAZARD') {
    aiInsight = 'Rintangan terdeteksi di bawah batas aman 10cm. Manuver putar arah atau berhenti darurat direkomendasikan.';
  } else if (prev.eventCategory === 'AI_ANOMALY') {
    aiInsight = 'Distribusi beban 8-servo tidak simetris. Reset stance ke posisi STAND direkomendasikan.';
  } else if (prev.eventCategory === 'OVERHEAT_WARNING') {
    aiInsight = 'Suhu mikrokontroler melebihi 35°C. Istirahatkan motor servo sejenak.';
  } else {
    aiInsight = 'Semua subsistem berjalan dalam batas toleransi normal.';
  }
}

return {
  json: {
    ...prev,
    aiInsight
  }
};

